// Package mergeconflict strips git conflict markers that fall inside
// regenerable directive sections and detects markers that remain.
// The merge driver uses it so a conflict inside generated content,
// which mdsmith fix rebuilds anyway, never blocks a merge.
package mergeconflict

import (
	"bytes"

	"github.com/jeduden/mdsmith/internal/archetype/gensection"
)

// StripSectionConflicts removes git conflict markers from lines
// that fall inside the sections named by names (the directive
// names regenerated by mdsmith fix, e.g. "catalog" and "include").
// Conflict markers outside these sections are left unchanged.
//
// Both standard (<<<<<<<, =======, >>>>>>>) and diff3
// (<<<<<<<, |||||||, =======, >>>>>>>) conflict styles are supported.
//
// The ======= separator is only stripped when it appears between
// <<<<<<< and >>>>>>> to avoid false positives with Markdown
// setext heading underlines.
func StripSectionConflicts(content []byte, names []string) []byte {
	lines := bytes.Split(content, []byte("\n"))
	var out [][]byte
	inSection := false
	inConflict := false

	for _, line := range lines {
		trimmed := bytes.TrimSpace(line)

		if matchesAnyStart(trimmed, names) {
			inSection = true
		}

		if inSection {
			if isOpen(trimmed) {
				inConflict = true
				continue
			}
			if inConflict && isClose(trimmed) {
				inConflict = false
				continue
			}
			if inConflict && isBase(trimmed) {
				continue
			}
			if inConflict && isSeparator(trimmed) {
				continue
			}
		}

		out = append(out, line)

		if matchesAnyEnd(trimmed, names) {
			inSection = false
			inConflict = false
		}
	}

	return bytes.Join(out, []byte("\n"))
}

func matchesAnyStart(line []byte, names []string) bool {
	for _, name := range names {
		if gensection.IsRawStartMarker(line, name) {
			return true
		}
	}
	return false
}

func matchesAnyEnd(line []byte, names []string) bool {
	for _, name := range names {
		if gensection.IsRawEndMarker(line, name) {
			return true
		}
	}
	return false
}

// isOpen returns true if the line opens a git conflict
// block (starts with <<<<<<<).
func isOpen(line []byte) bool {
	return bytes.HasPrefix(line, []byte("<<<<<<<"))
}

// isBase returns true if the line opens the base
// (ancestor) section in a diff3-style conflict block (starts
// with |||||||). This marker only appears when git is
// configured with merge.conflictstyle = diff3 or zdiff3.
func isBase(line []byte) bool {
	return bytes.HasPrefix(line, []byte("|||||||"))
}

// isSeparator returns true if the line is a git conflict
// separator (starts with =======). This is context-dependent:
// the same pattern is valid as a Markdown setext heading
// underline, so callers must check conflict state.
func isSeparator(line []byte) bool {
	return bytes.HasPrefix(line, []byte("======="))
}

// isClose returns true if the line closes a git conflict
// block (starts with >>>>>>>).
func isClose(line []byte) bool {
	return bytes.HasPrefix(line, []byte(">>>>>>>"))
}

// HasMarkers returns true if the content contains any
// git conflict markers. Only checks for unambiguous markers
// (<<<<<<< and >>>>>>>) to avoid setext heading false positives.
func HasMarkers(content []byte) bool {
	for _, line := range bytes.Split(content, []byte("\n")) {
		trimmed := bytes.TrimSpace(line)
		if isOpen(trimmed) || isClose(trimmed) {
			return true
		}
	}
	return false
}
